// Run after npm run build: node --import tsx tests/browser/mapping/browser-llm-panel-check.mjs
import assert from 'node:assert/strict';
import { spawn } from 'node:child_process';
import { mkdtemp, rm, readFile, writeFile } from 'node:fs/promises';
import { tmpdir, homedir } from 'node:os';
import { createServer } from 'node:net';
import path from 'node:path';
import { pathToFileURL } from 'node:url';
import { seedMappingFixture } from '../support/browser-mapping-fixture.mjs';
import { canvasSaveFixture } from '../../support/mappingDiagram.ts';
import { RevisionedDiagramService } from '../../../domain/core/diagrams/diagramService.ts';
import { singleDiagramScene, projectCanvasSnapshot } from '../../../domain/core/diagrams/projectDiagramCanvas.ts';
import { asciiSha256 } from '../../../domain/core/diagrams/asciiSha256.ts';
const { evaluate, waitFor, waitForSelector, withHeadlessBrowser, captureScreenshot } = await import(pathToFileURL(path.join(homedir(), '.codex/skills/front-end/browser-test.mjs')).href);
const root = await mkdtemp(path.join(tmpdir(), 'diagram-edit-ui-'));
let server;
try {
  await seedMappingFixture(root, { ascii: 'First\n+-- Existing\n|   `-- Child\n`-- Untouched', nodes: [] });
  const catalogPath = path.join(root, '.diagrams/representations/catalog.json');
  const catalog = JSON.parse(await readFile(catalogPath, 'utf8'));
  const scene = singleDiagramScene('First\n+-- Existing\n|   `-- Child\n`-- Untouched');
  const diagrams = new RevisionedDiagramService();
  scene.contents = { ...scene.contents,
    overview: diagrams.create({ id: 'overview', revision: 0, ascii: 'First\n+-- Existing\n|   `-- Child\n`-- Untouched', structureKind: 'tree' }).diagram,
    second: diagrams.create({ id: 'second', revision: 0, ascii: 'Second\n`-- Other', structureKind: 'tree' }).diagram };
  scene.root.children.push({ id: 'second', kind: 'diagram', contentId: 'second', position: { column: 35, row: 0 }, collapsed: false });
  const revision = catalog.revisions['revision-overview'];
  revision.content = { kind: 'canvas-history', history: canvasSaveFixture({ name: 'Fixture', scene }).history };
  revision.ascii = projectCanvasSnapshot(scene).ascii; revision.asciiSha256 = asciiSha256(revision.ascii);
  await writeFile(catalogPath, JSON.stringify(catalog));
  const port = await new Promise(resolve => { const s = createServer(); s.listen(0, '127.0.0.1', () => { const p = s.address().port; s.close(() => resolve(p)); }); });
  const url = `http://127.0.0.1:${port}`;
  server = spawn(process.execPath, ['scripts/dev/start-server.mjs', 'preview', '--http', '--pi', '--host', '127.0.0.1', '--port', String(port), '--strictPort'],
    { detached: true, env: { ...process.env, NEW_DIAGRAM_PROJECT_ROOT: root, NEW_DIAGRAMS_DIR: path.join(root, '.diagrams'), NEW_DIAGRAM_AGENT: 'fake' }, stdio: ['ignore', 'ignore', 'pipe'] });
  let errors = ''; server.stderr.on('data', c => { errors += c; });
  await waitFor(async () => (await fetch(url).catch(() => null))?.ok, { timeoutMs: 20000 }).catch(e => { throw Error(`${e}\n${errors}`); });
  await withHeadlessBrowser({ url: `${url}/mapping?diagram=representation-overview`, width: 1800, height: 1100,
    chromePath: process.env.CHROME_PATH, arguments: ['--no-sandbox', '--disable-gpu'] }, async ({ cdp }) => {
    const browserErrors = [];
    await cdp.send('Page.enable'); await cdp.send('Runtime.enable');
    cdp.on('Runtime.exceptionThrown', event => browserErrors.push(event.exceptionDetails));
    await cdp.send('Network.enable');
    const submittedEdits=[];
    cdp.on('Network.requestWillBeSent',event=>{ if(event.request.url.endsWith('/api/mapping/agent/diagram-edits') && event.request.postData) submittedEdits.push(JSON.parse(event.request.postData)); });
    const submittedCreates=[];
    cdp.on('Network.requestWillBeSent',event=>{ if(event.request.url.endsWith('/api/mapping/agent/tools/create-diagram') && event.request.postData) submittedCreates.push(JSON.parse(event.request.postData)); });
    cdp.on('Page.javascriptDialogOpening', () => void cdp.send('Page.handleJavaScriptDialog', { accept: true }));
    const send = cdp.send.bind(cdp);
    cdp.send = async (method, parameters) => {
      let timer;
      try { return await Promise.race([send(method, parameters), new Promise((_, reject) => { timer = setTimeout(() => reject(Error(`CDP timeout: ${method}`)), 15000); })]); }
      finally { clearTimeout(timer); }
    };
    const mouse = async (type, p, clickCount = 1, modifiers = 0) => cdp.send('Input.dispatchMouseEvent', { type, ...p, button: 'left', buttons: type === 'mouseReleased' ? 0 : 1, clickCount, modifiers });
    const click = async (selector, text) => {
      const p = await evaluate(cdp, `(() => { const e=[...document.querySelectorAll(${JSON.stringify(selector)})].find(e=>!${JSON.stringify(text)} || e.textContent.trim()===${JSON.stringify(text)}); if (!e || e.disabled) throw Error('Unavailable: '+${JSON.stringify(text ?? selector)}); const r=e.getBoundingClientRect(); for (const fraction of [0.5, 0.2, 0.8]) { const p={x:r.x+r.width/2,y:r.y+r.height*fraction}; if(e.contains(document.elementFromPoint(p.x,p.y))) return p; } throw Error('Occluded: '+${JSON.stringify(text ?? selector)}); })()`);
      await mouse('mousePressed', p); await mouse('mouseReleased', p);
    };
    const diagramPoint = async id => evaluate(cdp, `(() => {const r=document.querySelector('[data-grid-box="${id}"]').getBoundingClientRect();return{x:r.x+8,y:r.y+8};})()`);
    const select = async id => { const p = await evaluate(cdp, `(() => {const r=document.querySelector('[data-grid-box="${id}"]').getBoundingClientRect();return{x:r.x+2,y:r.bottom-6};})()`); await mouse('mousePressed', p, 2, 2); await mouse('mouseReleased', p, 2, 2); };
    const text = async () => evaluate(cdp, "[...document.querySelectorAll('[data-native-node] .mapping-poc-ascii')].map(el => el.textContent).join('\\n')");
    const key = async (value, modifiers = 0) => {
      await cdp.send('Input.dispatchKeyEvent', { type: 'keyDown', key: value, code: ['Escape','End','Enter','Delete'].includes(value) ? value : `Key${value.toUpperCase()}`, modifiers, windowsVirtualKeyCode: ({Escape:27,End:35,Enter:13,Delete:46})[value] ?? value.toUpperCase().charCodeAt(0) });
      await cdp.send('Input.dispatchKeyEvent', { type: 'keyUp', key: value, modifiers });
    };
    const nodePoint = async label => evaluate(cdp, `(() => { const e=[...document.querySelectorAll('[data-content-node-id][data-display-node-id]')].find(e=>e.textContent.trim()===${JSON.stringify(label)} && e.getBoundingClientRect().width>0); if(!e)throw Error('Missing node'); const r=e.getBoundingClientRect(); return {x:r.x+r.width/2,y:r.y+r.height/2}; })()`);
    const nodeClick = async label => { await waitFor(async()=>await evaluate(cdp,"!document.querySelector('.tl-hit-test-blocker:not(.tl-hit-test-blocker__hidden)')")); const p=await nodePoint(label); await mouse('mousePressed',p,2,2); await mouse('mouseReleased',p,2,2); };
    await waitForSelector(cdp, '[data-grid-box=second]');
    await waitFor(async () => (await diagramPoint('overview')).x > 320);
    const selectedLabels = async () => evaluate(cdp,"[...document.querySelectorAll('[data-native-node] [data-content-node-id].is-selected')].map(e=>e.textContent.trim()).sort()");
    const waitForSelection = async labels => waitFor(async()=>JSON.stringify(await selectedLabels())===JSON.stringify(labels)).catch(async error => {
      console.log('Selection mismatch', { expected: labels, actual: await selectedLabels(), hit: await evaluate(cdp,"[...document.querySelectorAll('[data-native-node] [data-content-node-id]')].map(e=>{const r=e.getBoundingClientRect();return {label:e.textContent,hit:document.elementFromPoint(r.x+r.width/2,r.y+r.height/2)?.outerHTML.slice(0,180)}})") });
      throw error;
    });
    const envelopes = async () => evaluate(cdp, `([...document.querySelectorAll('[data-selection-active=true]')].map(root=>{
      const id=root.dataset.selectionRoot, rect=document.querySelector('[data-native-node="floating:'+id+'"] .retained-selection')?.getBoundingClientRect();
      return {id,width:rect?.width,height:rect?.height};
    }))`);
    await nodeClick('Other');
    await nodeClick('First');
    await waitForSelection(['Child','Existing','First','Other','Untouched']);
    const originalEnvelopes = await envelopes();
    await nodeClick('Existing');
    await waitForSelection(['First','Other','Untouched']);
    assert.deepEqual(await envelopes(), originalEnvelopes, 'Removing an interior subtree preserves envelope identity and dimensions');
    await key('z',2);
    await waitForSelection(['Child','Existing','First','Other','Untouched']);
    await key('y',2);
    await waitForSelection(['First','Other','Untouched']);
    assert.deepEqual(await envelopes(), originalEnvelopes, 'Undo/redo updates membership without fragmenting the rectangle');
    await click('[aria-label="Menu"]');
    await click('button','Save workspace');
    await waitFor(async()=>await evaluate(cdp,"document.querySelector('.mapping-menu-status')?.textContent.includes('Workspace saved')"));
    await click('button','Restore workspace');
    await key('Escape');
    await waitForSelection(['First','Other','Untouched']);
    await waitFor(async()=>JSON.stringify(await envelopes())===JSON.stringify(originalEnvelopes));
    const selectionReloaded = new Promise(resolve => { const off=cdp.on('Page.loadEventFired',()=>{off();resolve();}); });
    await cdp.send('Page.reload',{ignoreCache:true}); await selectionReloaded;
    await waitForSelection(['First','Other','Untouched']);
    await waitFor(async()=>JSON.stringify(await envelopes())===JSON.stringify(originalEnvelopes));
    await key('Escape');
    await waitForSelection(['Other']);
    await key('Escape');
    await waitForSelection([]);
    await key('z',2); await key('z',2);
    await waitForSelection(['First','Other','Untouched']);
    assert.deepEqual(await envelopes(), originalEnvelopes, 'Reload and history synchronize highlights and rectangles without node clicks');
    await captureScreenshot(cdp,{output:process.env.SELECTION_SCREENSHOT_PATH ?? path.join(root,'selection-state.png')});
    console.log('PASS stable selection envelopes, chronological Escape, undo/redo and workspace restore state synchronization');
    await nodeClick('Existing');
    await waitForSelection(['Child','Existing','First','Other','Untouched']);
    await nodeClick('Child');
    await waitForSelection(['Existing','First','Other','Untouched']);
    await nodeClick('Existing');
    await waitForSelection(['First','Other','Untouched']);
    await nodeClick('First');
    await waitForSelection(['Other']);
    await nodeClick('Other');
    await waitFor(async()=>(await selectedLabels()).length===0);
    await select('overview');
    await waitForSelector(cdp,'[data-grid-box=overview][data-diagram-selected=true]');
    await nodeClick('Existing');
    await waitForSelection(['First','Untouched']);
    await nodeClick('First');
    await waitFor(async()=>(await selectedLabels()).length===0);
    console.log('PASS Ctrl-double-click subtree toggle, nested leaf removal, siblings, other diagrams and whole-diagram subtraction');
    await nodeClick('Existing');
    await waitForSelector(cdp,'.retained-selection-controls');
    await click('.retained-selection-controls button','Actions (A)');
    await key('b', 2); await key('l');
    await waitForSelector(cdp,'.llm-panel .prompt-body-text');
    assert.equal(await evaluate(cdp, "document.querySelector('[aria-label=\"LLM mode\"]').value"), 'edit-diagram');
    assert.equal(await evaluate(cdp, "document.querySelectorAll('.prompt-reference').length"), 1);
    const referenceCounts = async () => evaluate(cdp,"[...document.querySelectorAll('.prompt-body .prompt-reference small')].map(e=>e.textContent.match(/(\\d+) nodes?$/)?.[1]).map(Number)");
    await waitFor(async()=>JSON.stringify(await referenceCounts())==='[2]');
    await evaluate(cdp,"void (window.originalSelectionChip=document.querySelector('.prompt-body .prompt-reference'))");
    await nodeClick('Child');
    await waitFor(async()=>JSON.stringify(await referenceCounts())==='[1]');
    assert.ok(await evaluate(cdp,"window.originalSelectionChip===document.querySelector('.prompt-body .prompt-reference')"), 'Node deselection updates the existing widget in place');
    await key('z',2);
    await waitFor(async()=>JSON.stringify(await referenceCounts())==='[2]');
    await key('y',2);
    await waitFor(async()=>JSON.stringify(await referenceCounts())==='[1]');
    assert.ok(await evaluate(cdp,"window.originalSelectionChip===document.querySelector('.prompt-body .prompt-reference')"));
    await captureScreenshot(cdp,{output:process.env.REFERENCE_SCREENSHOT_PATH ?? path.join(root,'reference-decrement.png')});
    await nodeClick('Existing');
    await waitFor(async()=>(await referenceCounts()).length===0);
    await key('z',2);
    await waitFor(async()=>JSON.stringify(await referenceCounts())==='[1]');
    console.log('PASS one reference widget decrements 2 to 1, follows undo/redo, disappears on empty selection and restores once');
    await click('[aria-label="Close Workspace tools"]');
    await nodeClick('Other');
    await click('[aria-label="LLM sessions"] button[aria-current=page]');
